SELECT id, session_id, event_type, page, event_time, duration_sec, LEAD(duration_sec, 1, 0) OVER (PARTITION BY session_id ORDER BY duration_sec, id) AS next_duration_sec, COUNT(duration_sec) OVER (ORDER BY CAST(event_time AS BIGINT) RANGE BETWEEN 604800 PRECEDING AND CURRENT ROW) AS duration_sec_count_7d, SUM(duration_sec) OVER w_running AS cumulative_duration_sec, NTILE(3) OVER w_ordered AS duration_sec_bucket FROM web_events WINDOW w_running AS (PARTITION BY page ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_ordered AS (PARTITION BY page ORDER BY duration_sec, id)
